---@type ActionUtils
local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
local ECSComponent = import("Frame.ECS.ECSComponent")

---@class IllustratedHandbookComponent : ECSComponent
local IllustratedHandbookComponent = Class("IllustratedHandbookComponent", ECSComponent)


function IllustratedHandbookComponent:__init()
    self.name = "IllustratedHandbookComponent"
    self.eventGameSwitchLanguage_ = Events.AddListener(Constants.EventNames.GAME_SWITCH_LANGUAGE, Bind(self, self.onGameSwitchLanguageHandler_))
    -- addition collect
    ---@type table<string, table<string, integer>> @ 卡牌收集-收集的refId记录（key：收集类型，value：refId字典）
    self.additionCollectRefIdMap_ = {}
    ---@type table<string, integer>                @ 卡牌收集-收集的refId数量（key：收集类型，value：refId数量）
    self.additionCollectRefNumMap_ = {}
    ---@type table<string, integer>                @ 卡牌收集-已激活的目标值（key：收集类型，value：激活的目标值）
    self.additioActivateNumMap_ = {}
    ---@type table<string, CardCollectRewardsVo>   @ 卡牌收集-当前的收集奖励vo（key：收集类型，value：奖励vo）
    self.additionProgressVoMap_ = {}
    ---@type table<string, CardCollectRewardsVo[]> @ 卡牌收集-收集奖励vo列表（key：收集类型，value：奖励vo列表）
    self.additionRewardsVosMap_ = {}
    ---@type table<Constants.CardCollectionType, table<integer, CardCollectRewardsVo>> @ 奖励vo的记录（key：收集类型，value：奖励字典（key：目标值，value：奖励vo））
    self.additionRewardsVoDictMap_ = {}
    -- handbook collect
    ---@type table<integer, IllustratedHandbookCollectDojo> @ 图鉴收集-dojo记录（key：类型id，value：收集dojo）
    self.handbookCollectDojoMap_ = {}
    ---@type table<integer, boolean> @ 图鉴收集-new记录（key：收集类型，value：new记录字典（key：refId，value：是否显示new标记））
    self.handbookCollectNewIdMap_ = {}
    -- keyword collect
    ---@type table<integer, IllustratedHandbookKeywordEncyDojo> @ 关键词百科-dojo记录（key：关键词id，value：关键词dojo）
    self.keywordsEncyDojoMap_ = {}
    ---@type table<integer, boolean> @ 关键词百科-new记录（keya：关键词id，value：是否显示new标记）
    self.keywordsEncyNewIdMap_ = {}
    -- regionMap collect
    ---@type table<integer, IllustratedHandbookRegionMapDojo> @ 区域百科-dojo记录（key：区域地图id，value：区域百科dojo）
    self.regionMapEncyDojoMap_ = {}
    ---@type table<integer, boolean> @ 区域百科-new记录（keya：区域地图id，value：是否显示new标记）
    self.regionMapEncyNewIdMap_ = {}

    ---@type table<Constants.CardCollectionType, boolean> @ 开放的收集类型（key：收集类型，value：是否开放）
    self.cardCollectionTypeMap_ = {}
    for _, additionRewardsVo in ipairs(CfUtils.GetWholeVo(AutoIds.IdSetting4099, 'CardCollectRewardsVo')) do
        local collectType = checkInt(additionRewardsVo.collectType)
        self.cardCollectionTypeMap_[collectType] = true
    end

    ---@type Constants.CardCollectionType[] @ 已开放的收集类型列表
    self.cardCollectionTypeList_ = table.keys(self.cardCollectionTypeMap_)
    table.sort(self.cardCollectionTypeList_, function(aType, bType)
        return aType < bType
    end)
end


function IllustratedHandbookComponent:__delete()
    Events.RemoveListener(Constants.EventNames.GAME_SWITCH_LANGUAGE, self.eventGameSwitchLanguage_)
    self.name = nil
    self.eventGameSwitchLanguage_ = nil
    -- addition collect
    self.additionCollectRefIdMap_  = nil
    self.additionCollectRefNumMap_ = nil
    self.additioActivateNumMap_    = nil
    self.additionProgressVoMap_    = nil
    self.additionRewardsVosMap_    = nil
    self.additionRewardsVoDictMap_ = nil
    self.cardCollectionTypeMap_    = nil
    self.cardCollectionTypeList_   = nil
    -- handbook collect
    self.handbookCollectDojoMap_  = nil
    self.handbookCollectNewIdMap_ = nil
    -- keyword collect
    self.keywordsEncyDojoMap_  = nil
    self.keywordsEncyNewIdMap_ = nil
    -- regionMap collect
    self.regionMapEncyDojoMap_  = nil
    self.regionMapEncyNewIdMap_ = nil
end


