function IllustratedHandbookComponent:InitialCollectionInfo()
    self.handbookCollectDojoMap_  = {}
    self.handbookCollectNewIdMap_ = {}

    ---@type CardProgressionConstants
    local CardProgressionConstants = import('Game.CardProgression.CardProgressionConstants')
    ---@type CardComponent
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    ---@type CardSkinComponent
    local skinComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardSkinComponent)
    ---@type CatEggComponent
    local catBallComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)

    -------------------------------------------------
    -- init typeMap
    ---@param collectTypeVo IllustratedCollectionTypeVo
    for voIndex, collectTypeVo in ipairs(CfUtils.GetWholeVo(AutoIds.IdSetting913, 'IllustratedCollectionTypeVo')) do
        local collectType = checkInt(collectTypeVo.typeId)
        local collectDojo = IllustratedHandbookCollectDojo.New()
        collectDojo.typeVo = collectTypeVo
        collectDojo.typeId = collectType
        self.handbookCollectDojoMap_[collectType] = collectDojo

        local unlockRefIdMap = {}
        local localTypeKey = string.fmt(Constants.PlayerPrefsType.IllustratedCollectTypeNew, {_type_ = collectType})
        for _, unlockedId in ipairs(string.split2(CfUtils.GetLocalData(localTypeKey, ''), ',')) do
            unlockRefIdMap[tostring(unlockedId)] = true
        end
        self.handbookCollectNewIdMap_[collectType] = unlockRefIdMap
    end

    -------------------------------------------------
    -- init all role
    local roleCollectType = Constants.HandbookCollectionType.ROLE
    local roleCollectDojo = self.handbookCollectDojoMap_[roleCollectType]
    local unlockedRoleMap = checkTable(self.handbookCollectNewIdMap_[roleCollectType])
    ---@param cardVo CardVo
    for voIndex, cardVo in ipairs(CfUtils.GetWholeVo(AutoIds.IdSetting28, 'CardVo')) do
        if cardVo.isHandbook then
            local cardId = checkInt(cardVo.roleId)
            -- add total num
            roleCollectDojo.totalMap[tostring(cardId)] = true
            if cardComp:IsHasCard(cardId) then
                -- add owned num
                roleCollectDojo.ownedMap[tostring(cardId)] = true
                -- add unlock / locked num
                if not unlockedRoleMap[tostring(cardId)] then
                    roleCollectDojo.unlockMap[tostring(cardId)] = true
                else
                    roleCollectDojo.lockedMap[tostring(cardId)] = true
                end
            end
        end
    end

    -------------------------------------------------
    -- init all skin
    if Constants.HandbookCollectionType.SKIN ~= nil then
        local skinCollectType = Constants.HandbookCollectionType.SKIN
        local skinCollectDojo = self.handbookCollectDojoMap_[skinCollectType]
        local lockedSkinIdMap = checkTable(self.handbookCollectNewIdMap_[skinCollectType])
        ---@param skinVo CardSkinVo
        for voIndex, skinVo in ipairs(CfUtils.GetWholeVo(AutoIds.IdSetting113, 'CardSkinVo')) do
            local isOpendCard = roleCollectDojo.totalMap[tostring(skinVo.roleId)] ~= nil
            if isOpendCard and skinVo.isHandbook and skinVo.tag ~= CardProgressionConstants.SkinTag.Classic then  -- 原始皮不列入统计
                local skinId = checkInt(skinVo.skinId)
                -- add total num
                skinCollectDojo.totalMap[tostring(skinId)] = true
                if skinComp:IsHasSkin(skinId) then
                    -- add owned num
                    skinCollectDojo.ownedMap[tostring(skinId)] = true
                    -- add unlock / locked num
                    if not lockedSkinIdMap[tostring(skinId)] then
                        skinCollectDojo.unlockMap[tostring(skinId)] = true
                    else
                        skinCollectDojo.lockedMap[tostring(skinId)] = true
                    end
                end
            end
        end
    end

    -------------------------------------------------
    -- init all catType
    if Constants.HandbookCollectionType.CAT ~= nil then
        local catTypeCollectType = Constants.HandbookCollectionType.CAT
        local catTypeCollectDojo = self.handbookCollectDojoMap_[catTypeCollectType]
        local lockedCatTypeIdMap = checkTable(self.handbookCollectNewIdMap_[catTypeCollectType])
        ---@param typeVo CatTypeVo
        for voIndex, typeVo in ipairs(CfUtils.GetWholeVo(AutoIds.IdSetting55, 'CatTypeVo')) do
            if typeVo.isShow then
                local typeId = checkInt(typeVo.catTypeId)
                -- add total num
                catTypeCollectDojo.totalMap[tostring(typeId)] = true
                if cardComp:IsHasCardCatType(typeId) then
                    -- add owned num
                    catTypeCollectDojo.ownedMap[tostring(typeId)] = true
                    -- add unlock / locked num
                    if not lockedCatTypeIdMap[tostring(typeId)] then
                        catTypeCollectDojo.unlockMap[tostring(typeId)] = true
                    else
                        catTypeCollectDojo.lockedMap[tostring(typeId)] = true
                    end
                end
            end
        end
    end

    -------------------------------------------------
    -- init all catBallType
    local catBallTypeCollectType = Constants.HandbookCollectionType.CAT_BALL
    local catBallTypeCollectDojo = self.handbookCollectDojoMap_[catBallTypeCollectType]
    local lockedCatBallTypeIdMap = checkTable(self.handbookCollectNewIdMap_[catBallTypeCollectType])
    ---@param catBallVo CatBallVo
    for voIndex, catBallVo in ipairs(CfUtils.GetWholeVo(AutoIds.IdSetting6033, 'CatBallVo')) do
        if catBallVo.inHandBook then
            local ballId = checkInt(catBallVo.roleId)
            -- add total num
            catBallTypeCollectDojo.totalMap[tostring(ballId)] = true
            if catBallComp:HasDojoByCatId(ballId) then
                -- add owned num
                catBallTypeCollectDojo.ownedMap[tostring(ballId)] = true
                -- add unlock / locked num
                if not lockedCatBallTypeIdMap[tostring(ballId)] then
                    catBallTypeCollectDojo.unlockMap[tostring(ballId)] = true
                else
                    catBallTypeCollectDojo.lockedMap[tostring(ballId)] = true
                end
            end
        end
    end
end


function IllustratedHandbookComponent:InitialAdditionInfo(jsonData)
    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)

    -------------------------------------------------
    -- init rewardsVos Map / rewardsDict
    local initCardAdditionAttrMap  = {}
    self.additionRewardsVosMap_    = {}
    self.additionRewardsVoDictMap_ = {}
    ---@param additionRewardsVo CardCollectRewardsVo
    for voIndex, additionRewardsVo in ipairs(CfUtils.GetWholeVo(AutoIds.IdSetting4099, 'CardCollectRewardsVo')) do
        local collectType = tostring(additionRewardsVo.collectType)
        -- rewardsVos
        if not self.additionRewardsVosMap_[collectType] then
            self.additionRewardsVosMap_[collectType] = {}
        end
        table.insert(self.additionRewardsVosMap_[collectType], additionRewardsVo)
        -- rewardsDict
        if not self.additionRewardsVoDictMap_[collectType] then
            self.additionRewardsVoDictMap_[collectType] = {}
        end
        self.additionRewardsVoDictMap_[collectType][additionRewardsVo.collectTarget] = additionRewardsVo
        -- additionAttrMap
        initCardAdditionAttrMap[additionRewardsVo.attTypeId] = 0
    end

    -- 因为需要哪怕属性+0也要显示出来，所以就用0占位赋个初值
    for attrId, attrValue in pairs(initCardAdditionAttrMap) do
        cardComponent:GetAdditionAttrMap()[attrId] = attrValue
    end

    -------------------------------------------------
    -- init checkin data
    self.additioActivateNumMap_ = {}
    for _, infoData in ipairs(checkTable(jsonData)) do
        self:SetAdditionActivateNum(infoData.type, infoData.unlocked)
    end

    -------------------------------------------------
    -- init collect data
    self.additionCollectRefIdMap_  = {}
    self.additionCollectRefNumMap_ = {}
    local cardCollectionTypeList   = self:GetCardCollectionTypeList()
    for _, cardDojo in ipairs(cardComponent:GetAllCardTable()) do
        for _, type in ipairs(cardCollectionTypeList) do
            self:CheckAdditionStorage(type, cardDojo)
        end
    end

    -- update collectionProgressVo
    for collectType, _ in pairs(self.additionRewardsVosMap_) do
        self:UpdateAdditionProgressVo(collectType)
    end
end


function IllustratedHandbookComponent:InitialKeywordEncyInfo()
    self.keywordsEncyDojoMap_  = {}
    self.keywordsEncyNewIdMap_ = {}
    
    ---@type QuestComponent
    local questComp  = GameUtils.GetEntityCompByType(ECSComponentType.Constants.QuestComponent)
    local newQuestId = checkInt(questComp:GetCurQuestId())
    ---@param encyVo IllustratedEncyKeywordVo
    for _, encyVo in ipairs(CfUtils.GetWholeVo(AutoIds.IdSetting916, "IllustratedEncyKeywordVo")) do
        local encyId   = checkInt(encyVo.encyId)
        local unlockId = checkInt(encyVo.unlockNum)
        local encyDojo = IllustratedHandbookKeywordEncyDojo.New()
        encyDojo.encyVo   = encyVo
        encyDojo.isUnlock = unlockId <= newQuestId
        if encyDojo.isUnlock then
            self.keywordsEncyNewIdMap_[tostring(encyVo.encyId)] = false
        end
        self.keywordsEncyDojoMap_[tostring(encyId)] = encyDojo
    end

    local localNewId = CfUtils.GetLocalData(Constants.PlayerPrefsType.IllustratedKeywordEncyNew, '')
    for _, encyNewId in ipairs(string.split2(localNewId, ',')) do
        local encyDojo = self.keywordsEncyDojoMap_[tostring(encyNewId)]
        if encyDojo then
            encyDojo.isNewMark = true
            self.keywordsEncyNewIdMap_[tostring(encyNewId)] = true
        end
    end
end


function IllustratedHandbookComponent:InitialRegionMapInfo()
    self.regionMapEncyDojoMap_  = {}
    self.regionMapEncyNewIdMap_ = {}
    
    local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
    for _, areaVo in ipairs(ActionUtils.GetAllRegionPrimaryMapVo()) do
        local areaId   = checkInt(areaVo.id)
        local encyVo   = CfUtils.GetCfVo(AutoIds.IdSetting915, "IllustratedEncyAreaVo", 2000 + areaId)
        local encyDojo = IllustratedHandbookRegionMapDojo.New()
        encyDojo.areaId   = areaId
        encyDojo.encyVo   = encyVo
        encyDojo.isUnlock = ActionUtils.IsUnlockRegionalPoint(areaId)
        if encyDojo.isUnlock then
            self.regionMapEncyNewIdMap_[tostring(areaId)] = false
        end
        self.regionMapEncyDojoMap_[tostring(areaId)] = encyDojo
    end

    local localNewId = CfUtils.GetLocalData(Constants.PlayerPrefsType.IllustratedRegionEncyNew, '')
    for _, areaNewId in ipairs(string.split2(localNewId, ',')) do
        local encyDojo = self.regionMapEncyDojoMap_[tostring(areaNewId)]
        if encyDojo then
            encyDojo.isNewMark = true
            self.regionMapEncyNewIdMap_[tostring(areaNewId)] = true
        end
    end
end


