-------------------------------------------------------------------------------
-- reload vos cache
-------------------------------------------------------------------------------

function IllustratedHandbookComponent:onGameSwitchLanguageHandler_()
    for collectType, collectDojo in pairs(self.handbookCollectDojoMap_) do
        local newVo = CfUtils.GetCfVo(AutoIds.IdSetting913, 'IllustratedCollectionTypeVo', collectDojo.typeVo.refId)
        collectDojo.typeVo = newVo
    end

    for collectType, rewardsVo in pairs(self.additionProgressVoMap_) do
        local newVo = CfUtils.GetCfVo(AutoIds.IdSetting4099, 'CardCollectRewardsVo', rewardsVo.refId)
        self.additionProgressVoMap_[collectType] = newVo
    end

    for collectType, rewardsVoList in pairs(self.additionRewardsVosMap_) do
        for rewardsIndex, rewardsVo in ipairs(rewardsVoList) do
            local newVo = CfUtils.GetCfVo(AutoIds.IdSetting4099, 'CardCollectRewardsVo', rewardsVo.refId)
            rewardsVoList[rewardsIndex] = newVo
        end
    end

    for collectType, rewardsVoMap in pairs(self.additionRewardsVoDictMap_) do
        for collectTarget, rewardsVo in pairs(rewardsVoMap) do
            local newVo = CfUtils.GetCfVo(AutoIds.IdSetting4099, 'CardCollectRewardsVo', rewardsVo.refId)
            rewardsVoMap[collectTarget] = newVo
        end
    end

    for _, encyDojo in pairs(self.keywordsEncyDojoMap_) do
        local newVo = CfUtils.GetCfVo(AutoIds.IdSetting916, "IllustratedEncyKeywordVo", encyDojo.encyVo.refId)
        encyDojo.encyVo = newVo
    end

    for _, encyDojo in pairs(self.regionMapEncyDojoMap_) do
        local newVo = CfUtils.GetCfVo(AutoIds.IdSetting915, "IllustratedEncyAreaVo", encyDojo.encyVo.refId)
        encyDojo.encyVo = newVo
    end
end


