---@return boolean
function IllustratedHandbookComponent:CheckHandbookMainRedPoint()
    local hasRedPoint = self:CheckHandbookRoleRedPoint() or 
                        self:CheckHandbookSkinRedPoint() or 
                        self:CheckHandbookCatRedPoint() or
                        self:CheckHandbookCatBallRedPoint()
    return hasRedPoint
end

---@param collectionType integer
---@return boolean
function IllustratedHandbookComponent:CheckHandbookTypeRedPoint_(collectionType)
    local hasRedPoint = false
    local collectDojo = self:GetHandbookCollectDojo(collectionType)
    if collectDojo.lockedMap and table.count(collectDojo.lockedMap) > 0 then
        hasRedPoint = true
    end
    return hasRedPoint
end

