---@return boolean
function IllustratedHandbookComponent:CheckAdditionMainRedPoint()
    local hasRedPoint = self:CheckAdditionStarRedPoint() or 
                        self:CheckAdditionUrNumRedPoint() or 
                        self:CheckAdditionSkillRedPoint() or
                        self:CheckAdditionSkinLevelRedPoint()
    return hasRedPoint
end

---@param collectionType Constants.CardCollectionType
---@return boolean
function IllustratedHandbookComponent:CheckAdditionTypeRedPoint_(collectionType)
    local hasRedPoint = false
    local progressVo  = self:GetAdditionProgressVo(collectionType)
    if not progressVo then
        return false
    end

    local activateNum   = self:GetAdditionActivateNum(collectionType)
    local collectTarget = checkInt(progressVo.collectTarget)
    local isActivateAll = activateNum >= collectTarget
    if not isActivateAll then
        local collectNum  = self:GetAdditionCollectNum(collectionType)
        local isCanUnlock = collectNum >= collectTarget
        hasRedPoint = isCanUnlock
    end

    return hasRedPoint
end

---@return boolean
function IllustratedHandbookComponent:CheckAdditionStarRedPoint()
    local hasRedPoint = self:CheckAdditionTypeRedPoint_(Constants.CardCollectionType.STAR)
    GameUtils.SetRedPointNum(Constants.RedPointConst.StrengthenAdditionStar, hasRedPoint and 1 or 0)
    return hasRedPoint
end

---@return boolean
function IllustratedHandbookComponent:CheckAdditionUrNumRedPoint()
    local hasRedPoint = self:CheckAdditionTypeRedPoint_(Constants.CardCollectionType.UR_NUM)
    GameUtils.SetRedPointNum(Constants.RedPointConst.StrengthenAdditionUrNum, hasRedPoint and 1 or 0)
    return hasRedPoint
end

---@return boolean
