    local hasRedPoint = self:CheckAdditionTypeRedPoint_(Constants.CardCollectionType.SKILL)
    GameUtils.SetRedPointNum(Constants.RedPointConst.StrengthenAdditionSkill, hasRedPoint and 1 or 0)
    return hasRedPoint
end

