---@return IllustratedHandbookCollectDojo
function IllustratedHandbookComponent:GetHandbookCollectDojo(collectionType)
    return checkTable(self.handbookCollectDojoMap_[checkInt(collectionType)])
end


--- 保存本地新标记记录
---@param collectionType Constants.HandbookCollectionType
function IllustratedHandbookComponent:SaveCollectTypeNewMark_(collectionType)
    local newMarkIdList = {}
    for encyNewId, isNewMark in pairs(self.handbookCollectNewIdMap_[collectionType] or {}) do
        if isNewMark then
            table.insert(newMarkIdList, encyNewId)
        end
    end
    local localTypeKey = string.fmt(Constants.PlayerPrefsType.IllustratedCollectTypeNew, {_type_ = collectionType})
    CfUtils.WriteLocalData(localTypeKey, table.concat(newMarkIdList, ','))
end


--- 检测 图鉴收集 是否记录新获得
---@param collectionType Constants.HandbookCollectionType
---@param refId integer
function IllustratedHandbookComponent:CheckHandbookStorage(collectionType, refId)
    local collectDojo = self:GetHandbookCollectDojo(collectionType)

    -- 空内容直接退出
    if collectDojo.totalMap == nil then return end

    -- 是否需要被记录
    if collectDojo.totalMap[tostring(refId)] == nil then return end

    -- 是否已记录，避免重复记录
    if self:IsHandbookOwned(collectionType, refId) then return end

    -- add owned refId
    collectDojo.ownedMap[tostring(refId)] = true

    -- 是否未添加到解锁记录
    if not self:IsHandbookUnlock(collectionType, refId) then

        -- add locked refId
        collectDojo.lockedMap[tostring(refId)] = true
    
        -- 记录新解锁的
        self.handbookCollectNewIdMap_[collectionType] = self.handbookCollectNewIdMap_[collectionType] or {}
        self.handbookCollectNewIdMap_[collectionType][tostring(refId)] = true

        -- record newMark
        self:SaveCollectTypeNewMark_(collectionType)
    end
end


--- 添加 图鉴收集 待解锁refId
---@param collectionType Constants.HandbookCollectionType
---@param refId integer
function IllustratedHandbookComponent:UpdateHandbookUnlock(collectionType, refId)
    local collectDojo = self:GetHandbookCollectDojo(collectionType)

    -- 是否已记录，避免数量不一致
    if not self:IsHandbookOwned(collectionType, refId) then return end

    -- add unlock refId
    collectDojo.unlockMap[tostring(refId)] = true

    -- del locked refId
    collectDojo.lockedMap[tostring(refId)] = nil

    -- 清除new标记
    self.handbookCollectNewIdMap_[collectionType] = self.handbookCollectNewIdMap_[collectionType] or {}
    self.handbookCollectNewIdMap_[collectionType][tostring(refId)] = false

    -- record newMark
    self:SaveCollectTypeNewMark_(collectionType)
end


--- 清空 图鉴收集 全部待解锁refId
---@param collectionType Constants.HandbookCollectionType
function IllustratedHandbookComponent:CleanHandBookUnlock(collectionType)
    local collectDojo = self:GetHandbookCollectDojo(collectionType)

    for refId, _ in pairs(collectDojo.lockedMap) do
        -- add unlock refId
        collectDojo.unlockMap[tostring(refId)] = true
    end

    -- clean locked refId
    collectDojo.lockedMap = {}

    -- 清除new标记
    for refId, _ in pairs(self.handbookCollectNewIdMap_[collectionType] or {}) do
        self.handbookCollectNewIdMap_[collectionType][tostring(refId)] = false
    end

    -- record newMark
    self:SaveCollectTypeNewMark_(collectionType)
end


--- 是否 图鉴收集 已拥有refId
---@param collectionType Constants.HandbookCollectionType
---@param refId integer
---@return boolean
function IllustratedHandbookComponent:IsHandbookOwned(collectionType, refId)
    local collectDojo = self:GetHandbookCollectDojo(collectionType)
    return checkBool(collectDojo.ownedMap[tostring(refId)])
end


--- 是否 图鉴收集 已解锁refId
---@param collectionType Constants.HandbookCollectionType
---@param refId integer
---@return boolean
function IllustratedHandbookComponent:IsHandbookUnlock(collectionType, refId)
    local collectDojo = self:GetHandbookCollectDojo(collectionType)
    return checkBool(collectDojo.unlockMap[tostring(refId)])
end


--- 是否 图鉴收集 锁定的refId
---@param collectionType Constants.HandbookCollectionType
---@param refId integer
---@return boolean
function IllustratedHandbookComponent:IsHandbookLocked(collectionType, refId)
    local collectDojo = self:GetHandbookCollectDojo(collectionType)
    return checkBool(collectDojo.lockedMap[tostring(refId)])
end


-------------------------------------------------------------------------------
-- addition collect
-------------------------------------------------------------------------------

--- 刷新 当前进度收集奖励vo
---@param collectionType Constants.CardCollectionType
function IllustratedHandbookComponent:UpdateAdditionProgressVo(collectionType)
    local collectionType = tostring(collectionType)
    local rewardsVoList  = self.additionRewardsVosMap_[collectionType]
    local activateNum    = self:GetAdditionActivateNum(collectionType)

    -- check activate progress
    local progressRewardsVo = nil
    for _, rewardsVo in ipairs(rewardsVoList) do
        local isActivate = activateNum >= checkInt(rewardsVo.collectTarget)
        if not isActivate then
            progressRewardsVo = rewardsVo
            break
        end
    end

    -- check activate all
    if not progressRewardsVo then
        progressRewardsVo = rewardsVoList[#rewardsVoList]
    end

    -- update rewardsVo
    self.additionProgressVoMap_[collectionType] = progressRewardsVo
end

--- 获取 当前进度的收集奖励vo
---@param collectionType Constants.CardCollectionType
---@return CardCollectRewardsVo
function IllustratedHandbookComponent:GetAdditionProgressVo(collectionType)
    local collectionType = tostring(collectionType)
    return self.additionProgressVoMap_[collectionType]
end

--- 获取 卡牌收集奖励vo 通过目标数量
---@param collectionType Constants.CardCollectionType
---@param targetNum integer
---@return CardCollectRewardsVo
function IllustratedHandbookComponent:GetAdditionRewardsVoAt(collectionType, targetNum)
    local collectionType = tostring(collectionType)
    return checkTable(self.additionRewardsVoDictMap_[collectionType])[checkInt(targetNum)]
end


--- 设置 卡牌收集 已激活的奖励目标值
---@param collectionType Constants.CardCollectionType
---@param targetNum integer
function IllustratedHandbookComponent:SetAdditionActivateNum(collectionType, targetNum)
    if not self:HasCardCollectionType(collectionType) then return end
    local collectionType = tostring(collectionType)
    self.additioActivateNumMap_[collectionType] = checkInt(targetNum)
    -- update cardAdditionAttrMap
    local activateRewardsVo = self:GetAdditionRewardsVoAt(collectionType, targetNum)
    if activateRewardsVo then
        ---@type CardComponent
        local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        cardComponent:GetAdditionAttrMap()[activateRewardsVo.attTypeId] = checkInt(activateRewardsVo.attAddNum)
    end
end

--- 获取 卡牌收集 已激活的奖励目标值
---@param collectionType Constants.CardCollectionType
---@param targetNum integer
---@return integer
function IllustratedHandbookComponent:GetAdditionActivateNum(collectionType)
    local collectionType = tostring(collectionType)
    return checkInt(self.additioActivateNumMap_[collectionType])
end


--- 检测 卡牌收集 是否进行获得记录
---@param collectionType Constants.CardCollectionType
---@param cardDojo CardDojo
---@param cardSkinId integer | nil
function IllustratedHandbookComponent:CheckAdditionStorage(collectionType, cardDojo, cardSkinId)
    if not self:HasCardCollectionType(collectionType) then return end
    if collectionType == Constants.CardCollectionType.STAR then
        if checkInt(cardDojo.star) > 0 then
            self:SetAdditionCollectAt(Constants.CardCollectionType.STAR, cardDojo.cardId, cardDojo.star)
        end

    elseif collectionType == Constants.CardCollectionType.UR_NUM then
        if cardDojo:GetRare() >= Constants.RareType.UR then
            self:SetAdditionCollectAt(Constants.CardCollectionType.UR_NUM, cardDojo.cardId)
        end

    elseif collectionType == Constants.CardCollectionType.SKILL then
        local finalSkillLevel = checkInt(cardDojo.finalSkillLevel)
        local awakeningLevel  = checkInt(cardDojo.awakeningLevel)
        local growingSkillNum = 0
        if finalSkillLevel > 1 then -- 统计次数是从1之后
            growingSkillNum = growingSkillNum + (finalSkillLevel - 1)
        end
        if awakeningLevel > 1 then -- 统计次数是从1之后
            growingSkillNum = growingSkillNum + (awakeningLevel - 1)
        end
        if growingSkillNum > 0 then
            self:SetAdditionCollectAt(Constants.CardCollectionType.SKILL, cardDojo.cardId, growingSkillNum)
        end

    elseif collectionType == Constants.CardCollectionType.SKIN_LV then
        ---@type CardSkinComponent
        local skinComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardSkinComponent)
        if cardDojo then
            for _, skinId in ipairs(skinComp:GetCardSkinIdList(cardDojo.cardId)) do
                local skillLevel = skinComp:GetSkinLevelById(skinId)
                if skillLevel > 1 then
                    self:SetAdditionCollectAt(Constants.CardCollectionType.SKIN_LV, skinId, skillLevel - 1)
                end
            end
        else
            local skillLevel = skinComp:GetSkinLevelById(cardSkinId)
            if skillLevel > 1 then
                self:SetAdditionCollectAt(Constants.CardCollectionType.SKIN_LV, cardSkinId, skillLevel - 1)
            end
        end
    end
end

--- 设置 卡牌收集 收集的refId信息
---@param collectionType Constants.CardCollectionType
---@param refId integer
---@param addNum integer
function IllustratedHandbookComponent:SetAdditionCollectAt(collectionType, refId, addNum)
    local collectionType = tostring(collectionType)
    -- update collect refId
    if not self.additionCollectRefIdMap_[collectionType] then
        self.additionCollectRefIdMap_[collectionType] = {}
    end
    local newCollectNum = addNum and checkInt(addNum) or 1
    local oldCollectNum = checkInt(self.additionCollectRefIdMap_[collectionType][tostring(refId)])
    self.additionCollectRefIdMap_[collectionType][tostring(refId)] = newCollectNum

    -- update collect count
    if newCollectNum ~= oldCollectNum then
        if not self.additionCollectRefNumMap_[collectionType] then
            self.additionCollectRefNumMap_[collectionType] = 0
        end
        self.additionCollectRefNumMap_[collectionType] = self.additionCollectRefNumMap_[collectionType] - oldCollectNum
        self.additionCollectRefNumMap_[collectionType] = self.additionCollectRefNumMap_[collectionType] + newCollectNum
    end
end

--- 获取 卡牌收集 收集的总数量
---@param collectionType Constants.CardCollectionType
---@return integer
function IllustratedHandbookComponent:GetAdditionCollectNum(collectionType)
    local collectionType = tostring(collectionType)
    return checkInt(self.additionCollectRefNumMap_[collectionType])
end


