-- keyword ency
-------------------------------------------------------------------------------

---@return table<string, IllustratedHandbookKeywordEncyDojo>
function IllustratedHandbookComponent:GetKeywordsEncyDojoMap()
    return self.keywordsEncyDojoMap_
end


--- 保存本地新标记记录
function IllustratedHandbookComponent:SaveKeywordEncyNewMark_()
    local newMarkIdList = {}
    for encyNewId, isNewMark in pairs(self.keywordsEncyNewIdMap_) do
        if isNewMark then
            table.insert(newMarkIdList, encyNewId)
        end
    end
    CfUtils.WriteLocalData(Constants.PlayerPrefsType.IllustratedKeywordEncyNew, table.concat(newMarkIdList, ','))
end


--- 更新最新关卡的变化记录
---@param newQuestId integer
function IllustratedHandbookComponent:UpdateKeywordEncyProgress(newQuestId)
    -- update unlock state
    local newQuestId = checkInt(newQuestId)
    for _, encyDojo in pairs(self.keywordsEncyDojoMap_) do
        local encyVo   = encyDojo.encyVo
        local unlockId = checkInt(encyVo.unlockNum)
        encyDojo.isUnlock = unlockId <= newQuestId
        if encyDojo.isUnlock then
            -- 标记新解锁的
            if self.keywordsEncyNewIdMap_[tostring(encyVo.encyId)] == nil then
                self.keywordsEncyNewIdMap_[tostring(encyVo.encyId)] = true
                encyDojo.isNewMark = true
            end
        end
    end

    -- record newMark
    self:SaveKeywordEncyNewMark_()
end


--- 清除关键词的新标记
---@param encyId integer
function IllustratedHandbookComponent:ClearKeywordEncyNewMark(encyId)
    self.keywordsEncyNewIdMap_[tostring(encyId)] = false

    local encyDojo = self.keywordsEncyDojoMap_[tostring(encyId)]
    if encyDojo then
        encyDojo.isNewMark = false
    end

    -- record newMark
    self:SaveKeywordEncyNewMark_()
end


