--- 更新最新区域的变化记录
function IllustratedHandbookComponent:UpdateRegionMapEncyProgress()
    -- update unlock state
    for _, encyDojo in pairs(self.regionMapEncyDojoMap_) do
        local areaId = encyDojo.areaId
        encyDojo.isUnlock = ActionUtils.IsUnlockRegionalPoint(areaId)
        if encyDojo.isUnlock then
            -- 新解锁的
            if self.regionMapEncyNewIdMap_[tostring(areaId)] == nil then
                self.regionMapEncyNewIdMap_[tostring(areaId)] = true
                encyDojo.isNewMark = true
            end
        end
    end
    -- record newMark
    self:SaveRegionMapEncyNewMark_()
end


