function IllustratedHandbookComponent:ClearRegionMapEncyNewMark(areaId)
    self.regionMapEncyNewIdMap_[tostring(areaId)] = false

    local encyDojo = self.regionMapEncyDojoMap_[tostring(areaId)]
    if encyDojo then
        encyDojo.isNewMark = false
    end

    -- record newMark
    self:SaveRegionMapEncyNewMark_()
end


